const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'A' },
      { kind: 'text', payload: 'B' },
      { kind: 'text', payload: 'C' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1:1' },
      { kind: 'text', payload: 'AB : BC = 1 : 1' }
    ];
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var W = vp.widthDu || 480;
    var H = vp.heightDu || 320;
    var y = Math.round(H * 0.5);
    var x0 = Math.round(W * 0.16);
    var x2 = Math.round(W * 0.84);
    var xm = Math.round((x0 + x2) / 2);
    var tick = 10;
    var ink = '#26354a';
    var paths = [];

    paths.push({ id: 'segment', commands: visualSdk.polyline([[x0, y], [x2, y]]) });
    paths.push({ id: 'tickLeft', commands: visualSdk.polyline([[x0, y - tick], [x0, y + tick]]) });
    paths.push({ id: 'tickMid', commands: visualSdk.polyline([[xm, y - tick], [xm, y + tick]]) });
    paths.push({ id: 'tickRight', commands: visualSdk.polyline([[x2, y - tick], [x2, y + tick]]) });
    paths.push({ id: 'dotLeft', commands: visualSdk.circle(x0, y, 3.5) });
    paths.push({ id: 'dotMid', commands: visualSdk.circle(xm, y, 3.5) });
    paths.push({ id: 'dotRight', commands: visualSdk.circle(x2, y, 3.5) });

    var by = y + 38;
    var bracketA = visualSdk.polyline([[x0 + 6, y + 20], [x0 + 6, by], [xm - 6, by], [xm - 6, y + 20]]);
    var bracketB = visualSdk.polyline([[xm + 6, y + 20], [xm + 6, by], [x2 - 6, by], [x2 - 6, y + 20]]);
    paths.push({ id: 'bracketA', commands: bracketA });
    paths.push({ id: 'bracketB', commands: bracketB });

    var children = [
      { type: 'path', pathId: 'segment', stroke: ink, strokeWidth: 2 },
      { type: 'path', pathId: 'tickLeft', stroke: ink, strokeWidth: 2 },
      { type: 'path', pathId: 'tickMid', stroke: ink, strokeWidth: 2 },
      { type: 'path', pathId: 'tickRight', stroke: ink, strokeWidth: 2 },
      { type: 'path', pathId: 'dotLeft', stroke: ink, fill: ink },
      { type: 'path', pathId: 'dotMid', stroke: ink, fill: ink },
      { type: 'path', pathId: 'dotRight', stroke: ink, fill: ink },
      { type: 'path', pathId: 'bracketA', stroke: '#6b7a90', strokeWidth: 1.4 },
      { type: 'path', pathId: 'bracketB', stroke: '#6b7a90', strokeWidth: 1.4 }
    ];

    function label(x, yy, text, size, weight, color) {
      return {
        type: 'label',
        x: x,
        y: yy,
        text: text,
        fontSize: size,
        fontWeight: weight,
        fill: color,
        anchor: 'middle',
        baseline: 'middle'
      };
    }

    children.push(label(x0, y - 26, 'A', 16, '600', ink));
    children.push(label(xm, y - 26, 'B', 16, '600', ink));
    children.push(label(x2, y - 26, 'C', 16, '600', ink));
    children.push(label((x0 + xm) / 2, by + 18, '1', 15, '500', '#6b7a90'));
    children.push(label((xm + x2) / 2, by + 18, '1', 15, '500', '#6b7a90'));
    children.push(label(W / 2, by + 52, '1:1', 20, '700', ink));
    children.push(label(W / 2, by + 82, 'AB : BC = 1 : 1', 14, '400', '#4a5a72'));

    return {
      schemaVersion: 1,
      sceneId: 'segment-ratio-1-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
